    # Mark interior cells as 3
    for r, c in found_interior:
        result[r][c] = 3

    # Now find border cells - cells adjacent to the frame (either to 1s or to interior 3s)
    # A border cell is a 0 that is adjacent (one step) to a 1 or interior 3
    visited_border = set()
    border_queue = set()

