def generate_result_correct(grid):
    rows, cols = len(grid), len(grid[0])

    ones = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]
    if not ones:
        return grid

    min_r, max_r = min(c[0] for c in ones), max(c[0] for c in ones)
    min_c, max_c = min(c[1] for c in ones), max(c[1] for c in ones)

    result = [[0]*cols for _ in range(rows)]

    # First, mark the "interior" cells that will become 3
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if grid[r][c] == 0:
                cnt = sum(1 for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)] 
                         if 0 <= r+dr < rows and 0 <= c+dc < cols and grid[r+dr][c+dc] == 1)
                if cnt > 0:
                    result[r][c] = 3  # Interior cell with at least 1 1-neighbor becomes 3

    # Second, mark the "border" cells that become 2
    # These are 0s that are OUTSIDE the frame but within the extended zone
    for r in range(min_r, max_r + 1):  # Within frame rows
        for c in range(min_c, max_c + 1):  # Within frame cols
            if result[r][c] == 0 and grid[r][c] == 0:
                # It's a gap - stays 0
                pass

    for r in range(max(0, min_r - 1), min(rows, max_r + 2)):
        for c in range(max(0, min_c - 1), min(cols, max_c + 2)):
            if result[r][c] == 0 and grid[r][c] == 0:
                result[r][c] = 2

    return result

